import unittest
class TestDocker(unittest.TestCase):
    def test_dockerfile_order(self):
        with open('Dockerfile') as f:
            content = f.read()
        copy_req = content.find('COPY requirements.txt')
        pip_inst = content.find('RUN pip install')
        self.assertTrue(copy_req != -1 and pip_inst != -1 and copy_req < pip_inst, 'COPY requirements.txt must precede pip install')
if __name__ == '__main__':
    unittest.main()

